package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.os.*;
import okhttp3.*;
import org.json.*;
import java.util.*;
/** Matches the site's Phoenix presence channel. Only foreground activity keeps it open. */
final class NativePresence {
 interface Listener {void changed(JSONObject state,boolean connected);}
 private final Context context;private final Handler main=new Handler(Looper.getMainLooper());private final OkHttpClient client=new OkHttpClient.Builder().build();private final Set<Listener> listeners=new HashSet<>();private final Map<String,JSONObject> peers=new HashMap<>();private WebSocket socket;private String token="",user="";private boolean active,joined;private int epoch,ref,trackEpoch;private long lastFrame,retry=2000;private static final String TOPIC="realtime:platinados-presenca";
 NativePresence(Context c){context=c.getApplicationContext();}
 void listen(Listener l){listeners.add(l);l.changed(snapshot(),joined);}void remove(Listener l){listeners.remove(l);}
 private JSONObject snapshot(){JSONObject value=new JSONObject();for(Map.Entry<String,JSONObject> e:peers.entrySet())try{value.put(e.getKey(),e.getValue());}catch(JSONException ignored){}return value;}
 private void emit(){JSONObject s=snapshot();for(Listener l:new ArrayList<>(listeners))l.changed(s,joined);}
 void foreground(boolean value){active=value;if(value){if(socket==null)connect();}else{epoch++;trackEpoch++;main.removeCallbacksAndMessages(null);if(socket!=null)socket.cancel();socket=null;joined=false;peers.clear();emit();}}
 private void connect(){if(!active)return;int ticket=++epoch;new Thread(()->{try{String auth=AuthSession.token(context),uid=SessionPreferences.get(context).getString("user_id","");String[] cfg=SupabaseAuthClient.loadConfig();String url=cfg[0].replace("https://","wss://")+"/realtime/v1/websocket?apikey="+java.net.URLEncoder.encode(cfg[1],"UTF-8")+"&vsn=1.0.0";main.post(()->{if(!active||ticket!=epoch)return;token=auth;user=uid;socket=client.newWebSocket(new Request.Builder().url(url).build(),new WebSocketListener(){public void onOpen(WebSocket ws,Response response){main.post(()->{if(ticket!=epoch)return;lastFrame=android.os.SystemClock.elapsedRealtime();try{main.postDelayed(()->{if(ticket==epoch&&!joined)lost(ticket);},15000);send("phx_join",new JSONObject().put("access_token",token).put("config",new JSONObject().put("presence",new JSONObject().put("key",user).put("enabled",true)).put("broadcast",new JSONObject().put("ack",false).put("self",false)).put("private",false)));}catch(JSONException ignored){}});}public void onMessage(WebSocket ws,String message){main.post(()->{if(ticket==epoch)receive(message);});}public void onFailure(WebSocket ws,Throwable t,Response response){main.post(()->lost(ticket));}public void onClosed(WebSocket ws,int code,String reason){main.post(()->lost(ticket));}});});}catch(Exception e){main.post(()->lost(ticket));}},"presence-connect").start();}
 private void lost(int ticket){if(ticket!=epoch)return;epoch++;trackEpoch++;if(socket!=null)socket.cancel();socket=null;joined=false;emit();if(active){main.removeCallbacks(heartbeat);main.removeCallbacks(presenceRefresh);main.postDelayed(this::connect,retry);retry=Math.min(30000,retry*2);}}
 private void send(String event,JSONObject payload){try{if(socket!=null)socket.send(new JSONObject().put("topic",TOPIC).put("event",event).put("payload",payload).put("ref",String.valueOf(++ref)).toString());}catch(JSONException ignored){}}
 private final Runnable heartbeat=new Runnable(){public void run(){if(!active||socket==null)return;if(android.os.SystemClock.elapsedRealtime()-lastFrame>60000){lost(epoch);return;}if(!token.equals(SessionPreferences.get(context).getString("access_token",""))||SessionPreferences.get(context).getLong("expires_at",0)<=System.currentTimeMillis()){socket.cancel();socket=null;joined=false;emit();connect();return;}try{socket.send(new JSONObject().put("topic","phoenix").put("event","heartbeat").put("payload",new JSONObject()).put("ref",String.valueOf(++ref)).toString());}catch(JSONException ignored){}main.postDelayed(this,20000);}};
 private final Runnable presenceRefresh=new Runnable(){public void run(){if(!active||!joined)return;track();main.postDelayed(this,60000);}};
 private void receive(String text){if(text.length()>1048576)return;lastFrame=android.os.SystemClock.elapsedRealtime();try{JSONObject frame=new JSONObject(text);if(!TOPIC.equals(frame.optString("topic")))return;String event=frame.optString("event");JSONObject payload=frame.optJSONObject("payload");if(payload==null)return;if(event.equals("phx_reply")&&!payload.optString("status").equals("ok")&&!joined){lost(epoch);return;}if(event.equals("phx_reply")&&payload.optString("status").equals("ok")&&!joined){joined=true;retry=2000;main.removeCallbacks(heartbeat);main.postDelayed(heartbeat,20000);main.removeCallbacks(presenceRefresh);presenceRefresh.run();emit();}else if(event.equals("presence_state")){peers.clear();merge(payload,false);emit();}else if(event.equals("presence_diff")){JSONObject leaves=payload.optJSONObject("leaves"),joins=payload.optJSONObject("joins");if(leaves!=null)merge(leaves,true);if(joins!=null)merge(joins,false);emit();}else if(event.equals("phx_error")||event.equals("phx_close")){if(socket!=null)socket.cancel();lost(epoch);}}catch(JSONException ignored){}}
 private void merge(JSONObject change,boolean remove)throws JSONException{Iterator<String> ids=change.keys();while(ids.hasNext()){String id=ids.next();JSONObject value=change.optJSONObject(id);if(value==null)continue;JSONArray current=peers.containsKey(id)?peers.get(id).optJSONArray("metas"):new JSONArray(),changed=value.optJSONArray("metas");if(current==null)current=new JSONArray();if(changed==null)continue;JSONArray next=new JSONArray();for(int i=0;i<current.length();i++){JSONObject m=current.optJSONObject(i);boolean found=false;for(int k=0;k<changed.length();k++)if(m.optString("phx_ref").equals(changed.optJSONObject(k).optString("phx_ref")))found=true;if(!found)next.put(m);}if(!remove)for(int i=0;i<changed.length();i++)next.put(changed.optJSONObject(i));if(next.length()==0)peers.remove(id);else peers.put(id,new JSONObject().put("metas",next));}}
 void refresh(){if(active&&joined){main.removeCallbacks(presenceRefresh);track();main.postDelayed(presenceRefresh,60000);}}
 private boolean validTrack(int ticket){return ticket==trackEpoch&&active&&joined&&socket!=null;}
 private void publish(JSONObject profile,JSONObject game,int ticket){if(!validTrack(ticket))return;String status=PresencePolicy.status(profile.optString("status_personalizado","online"));try{if(!PresencePolicy.visible(status)){send("presence",new JSONObject().put("type","presence").put("event","untrack").put("payload",new JSONObject()));return;}String name=game==null?"":game.optString("nome",game.optString("name",""));send("presence",new JSONObject().put("type","presence").put("event","track").put("payload",new JSONObject().put("nome",profile.optString("nome")).put("slug",profile.optString("slug")).put("avatar",profile.optString("avatar_url")).put("status",status).put("jogo",name).put("jogo_fonte",PresencePolicy.gameSource(name)).put("device","android").put("online_at",System.currentTimeMillis())));}catch(JSONException ignored){}}
 private void track(){final int ticket=++trackEpoch;new AccountRepository(context).load(true,0,(rows,error)->{if(!validTrack(ticket)||error!=null||rows.length()==0)return;JSONObject profile=rows.optJSONObject(0);if(profile==null)return;if(!PresencePolicy.visible(profile.optString("status_personalizado","online"))){publish(profile,null,ticket);return;}new AccountRepository(context).currentSteam((games,steamError)->publish(profile,steamError==null&&games.length()>0?games.optJSONObject(0):null,ticket));});}
}
